function groupWalks(walks) {
    const groups = new Map();

    for (const walk of walks) {
        const place = walk.place.trim();
        if (!groups.has(place)) {
            groups.set(place, { visits: 0, minutes: 0 });
        }

        const summary = groups.get(place);
        summary.visits += 1;
        summary.minutes += walk.minutes;
    }

    return Array.from(groups, ([place, summary]) => ({
        place,
        visits: summary.visits,
        average: summary.minutes / summary.visits
    })).sort((left, right) =>
        left.place.localeCompare(right.place)
    );
}

const walks = [
    { place: "Canal", minutes: 32 },
    { place: "Park", minutes: 45 },
    { place: "Canal", minutes: 28 },
    { place: "Park", minutes: 39 }
];

for (const item of groupWalks(walks)) {
    const average = item.average.toFixed(1);
    console.log(`${item.place}: ${item.visits} visits, ${average} min`);
}

