using System;
using System.Collections.Generic;

class Program
{
    static Dictionary<string, int> CountWords(string text)
    {
        Dictionary<string, int> counts =
            new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        char[] separators = { ' ', '.', ',', '!', '?' };
        string[] words = text.Split(
            separators, StringSplitOptions.RemoveEmptyEntries);

        foreach (string word in words)
        {
            int previous;
            counts.TryGetValue(word, out previous);
            counts[word] = previous + 1;
        }
        return counts;
    }

    static void Main()
    {
        string note = "Rain at dawn, sun at noon. Rain again!";
        Dictionary<string, int> counts = CountWords(note);
        List<string> words = new List<string>(counts.Keys);
        words.Sort(StringComparer.OrdinalIgnoreCase);

        foreach (string word in words)
        {
            Console.WriteLine("{0}: {1}", word, counts[word]);
        }
    }
}

